UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kp4202-20-ft.pdf',
  descripcion_larga_es = $d$El Bastón Cuatro Apoyos Konfort Plus ofrece estabilidad y firmeza gracias a su base pequeña de cuatro puntos y su empuñadura de cuello en cisne, brindando un apoyo seguro a personas con movilidad reducida. Fabricado en aluminio resistente con una base en acero cromado, este bastón combina ligereza y durabilidad. Su altura es fácilmente ajustable por medio de un botón de pin, lo que permite adaptarse a diferentes estaturas.

El bastón de 4 apoyos con base pequeña Konfort Plus (negro) ofrece gran estabilidad y resistencia gracias a sus cuatro apoyos, con sistema de graduación de altura de ajuste firme, base en acero cromado y acabados de alta calidad. La empuñadura es de PVC. La ficha del fabricante indica capacidad de 125 kg y altura entre 72,5 y 95 cm.$d$,
  descripcion_larga_en = $d$The Konfort Plus Four-Prong Walking Stick provides stability and firmness through its small four-point base and swan-neck handle, offering secure support for individuals with reduced mobility. Made from durable aluminum with a chromed steel base, this cane combines lightweight construction with long-term durability. Its height is easily adjustable via a pin button, allowing adaptation to different statures.

The Konfort Plus small-base 4-point cane (black) offers great stability and strength thanks to its four supports, with a firm-locking height adjustment system, chrome-steel base and high-quality finishes. The handle is PVC. The manufacturer datasheet states 125 kg capacity and a height between 72.5 and 95 cm.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP4202-20"},{"clave":"Color","grupo":"Variante","valor":"Negro"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"125 kg"},{"clave":"Altura","grupo":"Dimensiones","valor":"72,5 - 95 cm"},{"clave":"Base","grupo":"Material","valor":"Acero cromado"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Cuatro apoyos para mayor estabilidad al caminar.","Base en acero cromado y altura graduable de 72,5 a 95 cm.","Capacidad de hasta 125 kg y empuñadura de PVC."],"beneficios_en":["Four supports for greater stability when walking.","Chrome-steel base and height adjustable from 72.5 to 95 cm.","Capacity up to 125 kg and PVC handle."],"valor_es":"Un bastón de cuatro apoyos para mayor estabilidad, con ficha técnica oficial de Konfort Plus (ficha de la variante cromo de la misma referencia base).","valor_en":"A four-point cane for greater stability, with official Konfort Plus datasheet (datasheet of the chrome variant of the same base model).","preguntas_frecuentes_es":[{"q":"¿Qué ventaja tiene frente a un bastón simple?","a":"Sus cuatro apoyos brindan mayor estabilidad, según el fabricante."},{"q":"¿Qué peso soporta?","a":"Hasta 125 kg."},{"q":"¿Qué altura permite?","a":"Entre 72,5 y 95 cm."},{"q":"¿Dónde descargo la ficha técnica de Bastón 4 Apoyos Base Pequeña Color Negro Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What advantage does it have over a simple cane?","a":"Its four supports provide greater stability, per the manufacturer."},{"q":"What weight does it support?","a":"Up to 125 kg."},{"q":"What height does it allow?","a":"Between 72.5 and 95 cm."},{"q":"Where can I download the Konfort Plus Four-Prong Small Base Walking Stick Black datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["bastón de 4 apoyos negro","bastón cuatro apoyos base pequeña","bastón de apoyo estable","bastón Konfort Plus","bastón ortopédico Colombia","ficha técnica KP4202-20"],"seo_keywords_en":["4-point cane black","small base quad cane","stable support cane","Konfort Plus cane","orthopaedic cane Colombia","KP4202-20 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCII6BK6SHAVBKVDRNCZBYNGN7KE?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
