UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kp4-832l6-20-ft.pdf',
  descripcion_larga_es = $d$El Bastón para Invidente Plegable Konfort Plus es una herramienta esencial para proporcionar seguridad y orientación a personas con discapacidad visual. Fabricado en aluminio anodizado, este bastón es ligero, seguro y resistente. Su sistema plegable en 4 secciones facilita su almacenamiento y transporte, mientras que su empuñadura plástica ergonómica y tapón giratorio brindan comodidad y estabilidad. Además, incluye bandas reflectivas para mejorar la visibilidad en entornos con poca luz.

El bastón para invidente plegable Konfort Plus es de aluminio anodizado, ligero, seguro y resistente. Se pliega en 4 secciones, incluye correa de seguridad, empuñadura de TPR, tapón giratorio, bandas reflectivas y estuche de transporte, con estructura liviana y almacenamiento sencillo.$d$,
  descripcion_larga_en = $d$The Konfort Plus Foldable Cane for the Visually Impaired is an essential tool to provide safety and orientation to people with visual disabilities. Made of anodized aluminum, this cane is lightweight, safe and resistant. Its 4-section folding system facilitates storage and transportation, while its ergonomic plastic handle and swivel tip provide comfort and stability. It also includes reflective bands to improve visibility in low-light environments.

The Konfort Plus folding cane for the blind is made of anodised aluminium, light, safe and sturdy. It folds into 4 sections and includes a safety strap, TPR handle, rotating tip, reflective bands and a carrying case, with a lightweight structure and simple storage.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP4-832L6-20"},{"clave":"Plegado","grupo":"Configuración","valor":"4 secciones"},{"clave":"Estructura / empuñadura","grupo":"Material","valor":"Aluminio anodizado / TPR"},{"clave":"Visibilidad","grupo":"Seguridad","valor":"Bandas reflectivas; correa de seguridad"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Plegable en 4 secciones con estuche de transporte.","Bandas reflectivas, correa de seguridad y tapón giratorio.","Aluminio anodizado liviano con empuñadura de TPR."],"beneficios_en":["Folds into 4 sections with carrying case.","Reflective bands, safety strap and rotating tip.","Lightweight anodised aluminium with TPR handle."],"valor_es":"Un bastón blanco plegable para personas con discapacidad visual, con ficha oficial de Konfort Plus.","valor_en":"A folding white cane for people with visual impairment, with official Konfort Plus datasheet.","preguntas_frecuentes_es":[{"q":"¿En cuántas secciones se pliega?","a":"En 4 secciones."},{"q":"¿Incluye estuche?","a":"Sí, incluye estuche de transporte."},{"q":"¿Tiene elementos de visibilidad?","a":"Sí, bandas reflectivas."},{"q":"¿Dónde descargo la ficha técnica de Bastón Para Invidente Plegable Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"How many sections does it fold into?","a":"4 sections."},{"q":"Does it include a case?","a":"Yes, a carrying case is included."},{"q":"Does it have visibility features?","a":"Yes, reflective bands."},{"q":"Where can I download the Konfort Plus Foldable White Cane for the Visually Impaired datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["bastón para invidente plegable","bastón blanco para personas ciegas","bastón guía plegable","bastón Konfort Plus","ayudas para la movilidad visual Colombia","ficha técnica KP4-832L6-20"],"seo_keywords_en":["folding cane for the blind","white cane for blind people","folding guide cane","Konfort Plus cane","visual mobility aids Colombia","KP4-832L6-20 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCLA3EXG5OOJEZXF63RP3WHZ62NA?version=4.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'baston-para-invidente-plegable-ref-kp4-832l6-20-konfort-plus';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kp4819-21-ft.pdf',
  descripcion_larga_es = $d$El bastón de 4 apoyos con linterna de Konfort Plus está diseñado para ofrecer una combinación única de seguridad, comodidad y funcionalidad. Su estructura de aluminio ligera pero duradera, junto con la base de 4 apoyos, proporciona una estabilidad excepcional, ideal para personas con alteraciones en el equilibrio o la fuerza. Ajustable en altura, este bastón se adapta perfectamente a cada usuario, ofreciendo un soporte ergonómico y personalizado.

El bastón de 4 apoyos con linterna Konfort Plus tiene base pequeña con contacto estable con el suelo, linterna y alarma, y un sistema de articulación fija que mejora el agarre y la facilidad de manejo. Su altura se gradúa en diez posiciones.$d$,
  descripcion_larga_en = $d$The Konfort Plus 4-support cane with flashlight is designed to offer a unique combination of safety, comfort and functionality. Its lightweight yet durable aluminum structure, together with the 4-support base, provides exceptional stability, ideal for people with balance or strength alterations. Height-adjustable, this cane adapts perfectly to each user, offering ergonomic and personalized support.

The Konfort Plus 4-point cane with flashlight has a small base with stable ground contact, a flashlight and alarm, and a fixed articulation system that improves grip and ease of handling. Its height adjusts in ten positions.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP4819-21"},{"clave":"Apoyos","grupo":"Configuración","valor":"4, base pequeña"},{"clave":"Alturas","grupo":"Configuración","valor":"10 posiciones"},{"clave":"Extras","grupo":"Extras","valor":"Linterna y alarma"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Linterna y alarma integradas para usarlo con poca luz y pedir ayuda.","Cuatro apoyos con base pequeña de contacto estable.","Altura graduable en diez posiciones."],"beneficios_en":["Integrated flashlight and alarm for use in low light and to call for help.","Four supports with a small, stable-contact base.","Height adjustable in ten positions."],"valor_es":"Un bastón de cuatro apoyos con linterna y alarma, con ficha oficial de Konfort Plus.","valor_en":"A four-point cane with flashlight and alarm, with official Konfort Plus datasheet.","preguntas_frecuentes_es":[{"q":"¿Tiene luz?","a":"Sí, incluye linterna y alarma."},{"q":"¿Cuántas posiciones de altura tiene?","a":"Diez."},{"q":"¿Cuántos apoyos tiene?","a":"Cuatro, con base pequeña."},{"q":"¿Dónde descargo la ficha técnica de Bastón 4 Apoyos Con Linterna Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"Does it have a light?","a":"Yes, it includes a flashlight and alarm."},{"q":"How many height positions does it have?","a":"Ten."},{"q":"How many supports does it have?","a":"Four, with a small base."},{"q":"Where can I download the Konfort Plus 4-Support Cane with Flashlight datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["bastón de 4 apoyos con linterna","bastón con luz y alarma","bastón cuatro apoyos","bastón Konfort Plus","bastón ortopédico Colombia","ficha técnica KP4819-21"],"seo_keywords_en":["4-point cane with flashlight","cane with light and alarm","quad cane","Konfort Plus cane","orthopaedic cane Colombia","KP4819-21 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCT5RYMYSVQJBMVMDVYBVP7FDL5M?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'baston-4-apoyos-con-linterna-ref-kp4819-21-konfort-plus';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kb311s-al19-ft.pdf',
  descripcion_larga_es = $d$La Muleta Convencional Konfort Plus está diseñada para proporcionar un apoyo seguro, cómodo y eficaz a personas con movilidad reducida. Fabricada en aluminio anodizado de color gris, es ligera pero resistente, con un centro reforzado que soporta una mayor carga y asegura durabilidad.

La muleta convencional Konfort Plus en aluminio anodizado gris (talla S) cuenta con ajuste de altura en su parte inferior, es ligera y brinda una asistencia segura al caminar. Pesa alrededor de 0,82 a 0,86 kg y se ofrece en tallas S, M y L.$d$,
  descripcion_larga_en = $d$The Konfort Plus Conventional Crutch is designed to provide safe, comfortable and effective support for people with reduced mobility. Made of anodized grey aluminum, it is lightweight yet resistant, with a reinforced center that supports a greater load and ensures durability. Available in size S, it fits users of short stature with ease. Its ergonomic design allows proper posture during walking.

The Konfort Plus conventional crutch in grey anodised aluminium (size S) has height adjustment at the bottom, is light and provides safe walking assistance. It weighs around 0.82 to 0.86 kg and comes in sizes S, M and L.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KB311S-AL19"},{"clave":"Talla / altura del usuario","grupo":"Talla","valor":"S: 92 - 112 cm"},{"clave":"Material","grupo":"Material","valor":"Aluminio anodizado gris"},{"clave":"Peso unitario","grupo":"Peso","valor":"0,82 - 0,86 kg"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Aluminio anodizado ligero (0,82 - 0,86 kg por muleta).","Ajuste de altura en la parte inferior.","Tres tallas (S, M, L) para adaptarse a la estatura."],"beneficios_en":["Light anodised aluminium (0.82 - 0.86 kg per crutch).","Height adjustment at the bottom.","Three sizes (S, M, L) to fit the user's height."],"valor_es":"Una muleta de aluminio con ajuste de altura, con ficha oficial de Konfort Plus.","valor_en":"An aluminium crutch with height adjustment, with official Konfort Plus datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué tallas hay?","a":"S (92-112 cm), M (112-132 cm) y L (132-152 cm)."},{"q":"¿De qué material es?","a":"Aluminio anodizado en color gris."},{"q":"¿Cómo se ajusta?","a":"Con ajuste de altura en la parte inferior."},{"q":"¿Dónde descargo la ficha técnica de Muleta Convencional En Aluminio Talla S Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"Which sizes are there?","a":"S (92-112 cm), M (112-132 cm) and L (132-152 cm)."},{"q":"What material is it?","a":"Grey anodised aluminium."},{"q":"How is it adjusted?","a":"With height adjustment at the bottom."},{"q":"Where can I download the Conventional Aluminum Crutch Size S Konfort Plus datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["muleta convencional talla S","muleta de aluminio","muletas ortopédicas","muleta Konfort Plus","muletas Colombia","ficha técnica KB311S-AL19"],"seo_keywords_en":["conventional crutch size S","aluminium crutch","orthopaedic crutches","Konfort Plus crutch","crutches Colombia","KB311S-AL19 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MC5S6QN2AQLBGRVLLHSZGDLFBI2A?version=1.1