UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kp3-856m-19-ft.pdf',
  descripcion_larga_es = $d$La Muleta Canadiense Doble Regulación de Konfort Plus está diseñada para proporcionar un apoyo firme y seguro a personas con movilidad reducida. Fabricada en aluminio anodizado, esta muleta es resistente y ligera, con un sistema de doble ajuste que permite regular tanto la altura de la muleta como la posición de la empuñadura. Disponible en dos tallas (L y M), se adapta a usuarios de distintas estaturas, ofreciendo una excelente ergonomía y estabilidad en cada paso.

La muleta canadiense de doble regulación Konfort Plus (talla M) permite regular la altura entre el suelo y la empuñadura y entre la empuñadura y la abrazadera. Es de aluminio anodizado, resistente y ligera, con tapones antideslizantes para mayor tracción, graduación por pines, extensión telescópica y no requiere ensamble.$d$,
  descripcion_larga_en = $d$The Konfort Plus Canadian Double Adjustment Crutch is designed to provide firm and safe support for people with reduced mobility. Made of anodized aluminum, this crutch is resistant and lightweight, with a double adjustment system that allows regulating both the crutch height and the handle position. Available in two sizes (L and M), it adapts to users of different statures, offering excellent ergonomics and stability in each step. The Canadian configuration distributes the load between the hand and forearm, reducing pressure on the wrist joint. It is suitable for prolonged rehabilitation and demanding clinical environments.

The Konfort Plus double-adjustment forearm crutch (size M) lets you adjust height between the floor and the handgrip and between the handgrip and the cuff. It is sturdy, light anodised aluminium with anti-slip tips for better traction, pin-based adjustment and telescopic extension, and requires no assembly.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP3-856M-19"},{"clave":"Material","grupo":"Material","valor":"Aluminio anodizado"},{"clave":"Regulación","grupo":"Ajustes","valor":"Doble: suelo-empuñadura y empuñadura-abrazadera"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Doble regulación de altura: suelo-empuñadura y empuñadura-abrazadera.","Aluminio anodizado ligero con tapones antideslizantes.","Graduación por pines, extensión telescópica y sin ensamble."],"beneficios_en":["Double height adjustment: floor-to-handgrip and handgrip-to-cuff.","Light anodised aluminium with anti-slip tips.","Pin adjustment, telescopic extension and no assembly."],"valor_es":"Una muleta canadiense de aluminio con doble regulación, con ficha oficial de Konfort Plus.","valor_en":"An aluminium forearm crutch with double adjustment, with official Konfort Plus datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué es la doble regulación?","a":"Permite ajustar la altura suelo-empuñadura y empuñadura-abrazadera."},{"q":"¿Requiere ensamble?","a":"No, viene lista para usar."},{"q":"¿Qué tallas hay?","a":"Tallas M (KP3-856M-19) y L (KP3-856L-19)."},{"q":"¿Dónde descargo la ficha técnica de Muleta Canadiense Doble Regulación Talla M Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What is double adjustment?","a":"It lets you adjust floor-to-handgrip and handgrip-to-cuff height."},{"q":"Does it require assembly?","a":"No, it comes ready to use."},{"q":"Which sizes are there?","a":"Sizes M (KP3-856M-19) and L (KP3-856L-19)."},{"q":"Where can I download the Canadian Double Adjustment Crutch Size M Konfort Plus datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["muleta canadiense talla M","muleta canadiense doble regulación","muleta con abrazadera","muleta Konfort Plus","muletas canadienses Colombia","ficha técnica KP3-856M-19"],"seo_keywords_en":["forearm crutch size M","double-adjustment forearm crutch","cuffed crutch","Konfort Plus crutch","forearm crutches Colombia","KP3-856M-19 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MC7Q3GJW6NWFH37JV5NZQTT57ATM?version=3.2&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'muleta-canadiense-doble-regulacion-talla-m-ref-kp3-856m-19-konfort-plus';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kp3-856m-19-ft.pdf',
  descripcion_larga_es = $d$La Muleta Canadiense Doble Regulación de Konfort Plus está diseñada para proporcionar un apoyo firme y seguro a personas con movilidad reducida. Fabricada en aluminio anodizado, esta muleta es resistente y ligera, con un sistema de doble ajuste que permite regular tanto la altura de la muleta como la posición de la empuñadura. Disponible en dos tallas (L y M), se adapta a usuarios de distintas estaturas, ofreciendo una excelente ergonomía y estabilidad en cada paso.

La muleta canadiense de doble regulación Konfort Plus (talla L) permite regular la altura entre el suelo y la empuñadura y entre la empuñadura y la abrazadera. Es de aluminio anodizado, resistente y ligera, con tapones antideslizantes para mayor tracción, graduación por pines, extensión telescópica y no requiere ensamble.$d$,
  descripcion_larga_en = $d$Double-regulation Canadian crutch from Konfort Plus, designed to provide firm, secure support for individuals with reduced mobility. Made of anodized aluminum, this crutch is resistant and lightweight, featuring a dual-adjustment system that regulates both the shaft height and the handle position. Available in two sizes (L and M), it adapts to users of different heights, delivering excellent ergonomics and stability with every step.

The Konfort Plus double-adjustment forearm crutch (size L) lets you adjust height between the floor and the handgrip and between the handgrip and the cuff. It is sturdy, light anodised aluminium with anti-slip tips for better traction, pin-based adjustment and telescopic extension, and requires no assembly.$d$,
