UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kp321-al-19-ft.pdf',
  descripcion_larga_es = $d$La Muleta Canadiense Adulto Integral Konfort Plus es una herramienta indispensable para mejorar la movilidad de personas con dificultades para caminar. Fabricada en aluminio anodizado, combina ligereza con resistencia, proporcionando un soporte estable y seguro. Con un diseño ergonómico y ajuste de altura desde 72 cm hasta 94 cm, esta muleta se adapta fácilmente a usuarios de diferentes estaturas, garantizando comodidad y funcionalidad en el uso diario.

La muleta canadiense para adulto Konfort Plus (color plata) está fabricada en aluminio anodizado, resistente, duradera y ligera, y brinda apoyo seguro y confortable durante la marcha. Tiene tapones antideslizantes, graduación de altura por pines y angulación para mayor estabilidad; no requiere ensamble.$d$,
  descripcion_larga_en = $d$The Konfort Plus Integrated Adult Canadian Crutch is an indispensable tool to improve mobility in people with walking difficulties. Manufactured in anodized aluminum, it combines lightness with strength, providing stable and safe support. With an ergonomic design and height adjustment from 72 cm to 94 cm, this crutch easily adapts to users of different heights, ensuring comfort and functionality in daily use.

The Konfort Plus adult forearm crutch (silver) is made of anodised aluminium, sturdy, durable and light, and provides safe, comfortable support when walking. It has anti-slip tips, pin height adjustment and angulation for greater stability; no assembly required.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP321-AL-19"},{"clave":"Material","grupo":"Material","valor":"Aluminio anodizado, color plata"},{"clave":"Regulación","grupo":"Ajustes","valor":"Pines"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Aluminio anodizado resistente y ligero.","Angulación para mayor estabilidad y mejor distribución del peso.","Tapones antideslizantes, graduación por pines y sin ensamble."],"beneficios_en":["Sturdy, light anodised aluminium.","Angulation for greater stability and better weight distribution.","Anti-slip tips, pin adjustment and no assembly."],"valor_es":"Una muleta canadiense de aluminio para adulto, con ficha oficial de Konfort Plus.","valor_en":"An aluminium adult forearm crutch, with official Konfort Plus datasheet.","preguntas_frecuentes_es":[{"q":"¿Es para adultos?","a":"Sí, es una muleta canadiense para adulto."},{"q":"¿Cómo se regula la altura?","a":"Por medio de pines."},{"q":"¿Requiere ensamble?","a":"No."},{"q":"¿Dónde descargo la ficha técnica de Muleta Canadiense Adulto Integral Color Plata Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"Is it for adults?","a":"Yes, it is an adult forearm crutch."},{"q":"How is height adjusted?","a":"By pins."},{"q":"Does it require assembly?","a":"No."},{"q":"Where can I download the Konfort Plus Integrated Adult Canadian Crutch Silver Color datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["muleta canadiense adulto","muleta de aluminio plata","muleta con apoyo de antebrazo","muleta Konfort Plus","muletas Colombia","ficha técnica KP321-AL-19"],"seo_keywords_en":["adult forearm crutch","silver aluminium crutch","forearm support crutch","Konfort Plus crutch","crutches Colombia","KP321-AL-19 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCDFBN7Y2S5NFN3BC3SDOIGSLVQM?version=2.2&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
