UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kp4202-20-ft.pdf',
  descripcion_larga_es = $d$El Bastón Cuatro Apoyos Konfort Plus ofrece estabilidad y firmeza gracias a su base pequeña de cuatro puntos y su empuñadura de cuello en cisne, brindando un apoyo seguro a personas con movilidad reducida. Fabricado en aluminio resistente con una base en acero cromado, este bastón combina ligereza y durabilidad. Su altura es fácilmente ajustable por medio de un botón de pin, lo que permite adaptarse a diferentes estaturas.

El bastón de 4 apoyos con base pequeña Konfort Plus (cromo) ofrece gran estabilidad y resistencia gracias a sus cuatro apoyos, con sistema de graduación de altura de ajuste firme, base en acero cromado y acabados de alta calidad. La empuñadura es de PVC. La ficha del fabricante indica capacidad de 125 kg y altura entre 72,5 y 95 cm.$d$,
  descripcion_larga_en = $d$The Konfort Plus Four-Prong Walking Stick provides stability and firmness through its small four-point base and swan-neck handle, offering secure support for individuals with reduced mobility. Made from durable aluminum with a chromed steel base, this cane combines lightweight construction with long-term durability. Its height is easily adjustable via a pin button, allowing adaptation to different statures.

The Konfort Plus small-base 4-point cane (chrome) offers great stability and strength thanks to its four supports, with a firm-locking height adjustment system, chrome-steel base and high-quality finishes. The handle is PVC. The manufacturer datasheet states 125 kg capacity and a height between 72.5 and 95 cm.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP4202-22"},{"clave":"Color","grupo":"Variante","valor":"Cromo"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"125 kg"},{"clave":"Altura","grupo":"Dimensiones","valor":"72,5 - 95 cm"},{"clave":"Base","grupo":"Material","valor":"Acero cromado"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Cuatro apoyos para mayor estabilidad al caminar.","Base en acero cromado y altura graduable de 72,5 a 95 cm.","Capacidad de hasta 125 kg y empuñadura de PVC."],"beneficios_en":["Four supports for greater stability when walking.","Chrome-steel base and height adjustable from 72.5 to 95 cm.","Capacity up to 125 kg and PVC handle."],"valor_es":"Un bastón de cuatro apoyos para mayor estabilidad, con ficha técnica oficial de Konfort Plus (ficha de la variante cromo de la misma referencia base).","valor_en":"A four-point cane for greater stability, with official Konfort Plus datasheet (datasheet of the chrome variant of the same base model).","preguntas_frecuentes_es":[{"q":"¿Qué ventaja tiene frente a un bastón simple?","a":"Sus cuatro apoyos brindan mayor estabilidad, según el fabricante."},{"q":"¿Qué peso soporta?","a":"Hasta 125 kg."},{"q":"¿Qué altura permite?","a":"Entre 72,5 y 95 cm."},{"q":"¿Dónde descargo la ficha técnica de Bastón 4 Apoyos Base Pequeña Color Cromo Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What advantage does it have over a simple cane?","a":"Its four supports provide greater stability, per the manufacturer."},{"q":"What weight does it support?","a":"Up to 125 kg."},{"q":"What height does it allow?","a":"Between 72.5 and 95 cm."},{"q":"Where can I download the Konfort Plus Four-Prong Small Base Walking Stick Chrome datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["bastón de 4 apoyos cromo","bastón cuatro apoyos base pequeña","bastón de apoyo estable","bastón Konfort Plus","bastón ortopédico Colombia","ficha técnica KP4202-22"],"seo_keywords_en":["4-point cane chrome","small base quad cane","stable support cane","Konfort Plus cane","orthopaedic cane Colombia","KP4202-22 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCII6BK6SHAVBKVDRNCZBYNGN7KE?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'baston-4-apoyos-base-pequena-color-cromo-ref-kp4202-22-konfort-plus';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kp4152-20-ft.pdf',
  descripcion_larga_es = $d$El Bastón Cuello de Cisne Konfort Plus está diseñado para proporcionar un apoyo seguro y ergonómico, ideal para quienes requieren asistencia en su movilidad diaria. Fabricado en aluminio resistente y ligero, cuenta con una empuñadura ergonómica de espuma y un sistema de graduación de altura ajustable desde 77 cm hasta 100 cm, lo que lo hace adecuado para usuarios de diferentes estaturas. Su diseño de cuello de cisne distribuye mejor el peso del usuario, proporcionando mayor estabilidad.

El bastón cuello de cisne con correa de seguridad Konfort Plus (cromo) es de aluminio, seguro, ligero y resistente, con graduación de altura de ajuste firme y empuñadura de PVC de fácil limpieza y larga duración. Su correa de seguridad evita que se caiga y su diseño elegante conserva acabados de alta calidad; la ficha indica capacidad de 125 kg.$d$,
  descripcion_larga_en = $d$The Swan-Neck Cane Konfort Plus is designed to provide safe, ergonomic support, ideal for those requiring assistance in daily mobility. Made from durable, lightweight aluminum, it features an ergonomic foam handle and an adjustable height graduation system from 77 cm to 100 cm, making it suitable for users of different statures. Its swan-neck design better distributes the user's weight, providing greater stability.

The Konfort Plus swan-neck cane with safety strap (chrome) is aluminium, safe, light and sturdy, with firm-locking height adjustment and an easy-to-clean, long-lasting PVC handle. Its safety strap keeps it from dropping and its elegant design keeps high-quality finishes; the datasheet states a 125 kg capacity.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP4152-22"},{"clave":"Color","grupo":"Variante","valor":"Cromo"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"125 kg"},{"clave":"Material","grupo":"Material","valor":"Aluminio; empuñadura PVC"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Cuello de cisne con correa de seguridad para no soltarlo.","Aluminio ligero y resistente con capacidad de 125 kg.","Empuñadura PVC de fácil limpieza y altura graduable."],"beneficios_en":["Swan-neck with safety strap to keep hold of it.","Light, sturdy aluminium with 125 kg capacity.","Easy-clean PVC handle and adjustable height."],"valor_es":"Un bastón cuello de cisne con correa de seguridad, con ficha oficial de Konfort Plus (ficha compartida con los colores de la misma referencia).","valor_en":"A swan-neck cane with safety strap, with official Konfort Plus datasheet (shared across the colours of the same model).","preguntas_frecuentes_es":[{"q":"¿Qué incluye de seguridad?","a":"Una correa de seguridad en la empuñadura."},{"q":"¿Qué peso soporta?","a":"125 kg."},{"q":"¿De qué es la empuñadura?","a":"De PVC, de fácil limpieza y larga duración."},{"q":"¿Dónde descargo la ficha técnica de Bastón Cuello De Cisne Y Correa De Seguridad Color Cromo Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What safety feature does it include?","a":"A safety strap on the handle."},{"q":"What weight does it support?","a":"125 kg."},{"q":"What is the handle made of?","a":"PVC, easy to clean and long-lasting."},{"q":"Where can I download the Swan-Neck Cane with Safety Strap Chrome Color Konfort Plus datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["bastón cuello de cisne cromo","bastón con correa de seguridad","bastón de aluminio","bastón Konfort Plus","bastón ortopédico Colombia","ficha técnica KP4152-22"],"seo_keywords_en":["swan-neck cane chrome","cane with safety strap","aluminium cane","Konfort Plus cane","orthopaedic cane Colombia","KP4152-22 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCFH732SK5VNCGDDHNRFRBNH4264?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
